import type { Server, Tunnel, BirdVarsConfig } from '@/types'

/**
 * Generate BIRD vars.conf content for a server
 */
export function generateVarsConf(config: BirdVarsConfig): string {
  const lines: string[] = [
    '# BIRD Configuration - Generated by BGP Panel',
    `# Generated at: ${new Date().toISOString()}`,
    '',
    `define LOCAL_ASN = ${config.local_asn};`,
    `define LOCAL_V6_kernel = ${config.local_v6_kernel};`,
  ]

  if (config.local_v4_kernel) {
    lines.push(`define LOCAL_V4_kernel = ${config.local_v4_kernel};`)
  }

  if (config.bb_v4_prefix) {
    lines.push(`define BB_V4_Prefix = ${config.bb_v4_prefix};`)
  }

  if (config.bb_v4) {
    lines.push(`define BB_V4 = ${config.bb_v4};`)
  }

  if (config.bb_v4_prefix_check) {
    lines.push(`define BB_V4_Prefix_check = ${config.bb_v4_prefix_check};`)
  }

  if (config.bb_ospf_v4) {
    lines.push(`define BB_OSPF_V4 = ${config.bb_ospf_v4};`)
  }

  lines.push(
    `define BB_V6 = ${config.bb_v6};`,
    `define BB_OSPF_V6 = ${config.bb_ospf_v6};`,
    `define BB_V6_Prefix = ${config.bb_v6_prefix};`,
    `define BB_V6_Prefix_check = ${config.bb_v6_prefix_check};`,
    '',
    `define MY_COMMUNITY = ${config.my_community};`,
    `define MY_REGION = ${config.my_region};`,
    `define MY_COUNTRY = ${config.my_country};`,
    `define MY_NODE = ${config.my_node};`,
    '',
    `router id ${config.router_id};`,
    '',
    'function kernel_route_hack(){',
    '}',
  )

  return lines.join('\n')
}

/**
 * Generate vars.conf from Server object
 */
export function generateServerVarsConf(server: Server, settings: {
  backbone_v4_prefix?: string
  backbone_v6_prefix: string
  local_asn: number
}): string {
  const config: BirdVarsConfig = {
    local_asn: server.local_asn,
    local_v6_kernel: server.ipv6_address,
    local_v4_kernel: server.ipv4_address || undefined,
    bb_v4_prefix: settings.backbone_v4_prefix || undefined,
    bb_v4: server.ipv4_address || undefined,
    bb_v4_prefix_check: settings.backbone_v4_prefix 
      ? `[${settings.backbone_v4_prefix}{128,128}]` 
      : undefined,
    bb_ospf_v4: server.ipv4_address 
      ? `${server.ipv4_address}/32` 
      : undefined,
    bb_v6: server.ipv6_address,
    bb_ospf_v6: `${server.ipv6_address}/128`,
    bb_v6_prefix: settings.backbone_v6_prefix,
    bb_v6_prefix_check: `[${settings.backbone_v6_prefix}{128,128}]`,
    my_community: server.local_asn,
    my_region: server.region_code,
    my_country: server.country_code,
    my_node: server.node_id,
    router_id: server.router_id || server.ipv4_address || '0.0.0.1',
  }

  return generateVarsConf(config)
}

/**
 * Generate RR session config (rr.conf on node side)
 */
export function generateRRSessionConfig(
  node: Server,
  rr: Server,
  options: {
    importFilter?: string
    exportFilter?: string
    multihop?: number
  } = {}
): string {
  const lines: string[] = [
    '# RR Session Configuration',
    `# Node: ${node.name} -> RR: ${rr.name}`,
    `# Generated at: ${new Date().toISOString()}`,
    '',
    `protocol bgp rr_${rr.icao_code.toLowerCase()}_v6 from ibgp_rr {`,
    `    neighbor ${rr.ipv6_address} as ${rr.local_asn};`,
    `    description "RR ${rr.name}";`,
  ]

  if (options.multihop && options.multihop > 1) {
    lines.push(`    multihop ${options.multihop};`)
  }

  if (options.importFilter) {
    lines.push(`    import where ${options.importFilter};`)
  } else {
    lines.push(`    import where rr_import(${node.region_code}, ${node.country_code});`)
  }

  if (options.exportFilter) {
    lines.push(`    export where ${options.exportFilter};`)
  } else {
    lines.push(`    export where rr_export(${rr.region_code}, ${rr.country_code});`)
  }

  lines.push('}')

  return lines.join('\n')
}

/**
 * Generate Node session config (node.conf on RR side)
 */
export function generateNodeSessionConfig(
  rr: Server,
  node: Server,
  options: {
    importFilter?: string
    exportFilter?: string
    multihop?: number
  } = {}
): string {
  const lines: string[] = [
    '# Node Session Configuration',
    `# RR: ${rr.name} -> Node: ${node.name}`,
    `# Generated at: ${new Date().toISOString()}`,
    '',
    `protocol bgp node_${node.icao_code.toLowerCase()}_${node.node_id}_v6 from ibgp_rr {`,
    `    neighbor ${node.ipv6_address} as ${node.local_asn};`,
    `    description "Node ${node.name}";`,
    '    rr client;',
  ]

  if (options.multihop && options.multihop > 1) {
    lines.push(`    multihop ${options.multihop};`)
  }

  if (options.importFilter) {
    lines.push(`    import where ${options.importFilter};`)
  } else {
    lines.push(`    import where rr_import(${node.region_code}, ${node.country_code});`)
  }

  if (options.exportFilter) {
    lines.push(`    export where ${options.exportFilter};`)
  } else {
    lines.push(`    export where rr_export(${rr.region_code}, ${rr.country_code});`)
  }

  lines.push('}')

  return lines.join('\n')
}

/**
 * Generate WireGuard interface configuration
 */
export function generateWireGuardConfig(
  tunnel: Tunnel,
  serverA: Server,
  serverB: Server,
  side: 'a' | 'b',
  privateKey: string
): string {
  const isA = side === 'a'
  const local = isA ? serverA : serverB
  const remote = isA ? serverB : serverA
  const localIp = isA ? tunnel.tunnel_ipv6_a : tunnel.tunnel_ipv6_b
  const remoteIp = isA ? tunnel.tunnel_ipv6_b : tunnel.tunnel_ipv6_a
  const remotePubKey = isA ? tunnel.wg_public_key_b : tunnel.wg_public_key_a

  const lines: string[] = [
    '[Interface]',
    `# Tunnel: ${serverA.name} <-> ${serverB.name}`,
    `PrivateKey = ${privateKey}`,
    `ListenPort = ${tunnel.wg_port}`,
    '',
    '[Peer]',
    `# Remote: ${remote.name}`,
    `PublicKey = ${remotePubKey}`,
    `Endpoint = ${remote.ssh_host}:${tunnel.wg_port}`,
    `AllowedIPs = ${remoteIp}/128`,
    'PersistentKeepalive = 25',
  ]

  return lines.join('\n')
}

/**
 * Generate OSPF interface configuration
 */
export function generateOSPFInterfaceConfig(
  tunnel: Tunnel,
  serverA: Server,
  serverB: Server,
  side: 'a' | 'b'
): string {
  const interfaceName = `wg_${serverA.icao_code.toLowerCase()}_${serverB.icao_code.toLowerCase()}`
  
  const lines: string[] = [
    `# OSPF Interface for tunnel ${serverA.name} <-> ${serverB.name}`,
    `interface "${interfaceName}" {`,
    `    type ${tunnel.ospf_type || 'ptp'};`,
    `    cost ${tunnel.ospf_cost || 10};`,
  ]

  if (tunnel.ospf_password) {
    lines.push(`    authentication cryptographic;`)
    lines.push(`    password "${tunnel.ospf_password}";`)
  }

  lines.push('};')

  return lines.join('\n')
}

/**
 * Generate network interface setup script
 */
export function generateInterfaceSetupScript(
  tunnel: Tunnel,
  serverA: Server,
  serverB: Server,
  side: 'a' | 'b'
): string {
  const isA = side === 'a'
  const interfaceName = `wg_${serverA.icao_code.toLowerCase()}_${serverB.icao_code.toLowerCase()}`
  const localIp = isA ? tunnel.tunnel_ipv6_a : tunnel.tunnel_ipv6_b

  const lines: string[] = [
    '#!/bin/bash',
    '# Auto-generated tunnel setup script',
    `# Tunnel: ${serverA.name} <-> ${serverB.name}`,
    '',
    `INTERFACE="${interfaceName}"`,
    `LOCAL_IP="${localIp}"`,
    '',
    '# Create WireGuard interface',
    `ip link add dev $INTERFACE type wireguard`,
    `wg setconf $INTERFACE /etc/wireguard/$INTERFACE.conf`,
    `ip -6 addr add $LOCAL_IP/127 dev $INTERFACE`,
    `ip link set $INTERFACE up`,
    '',
    '# Reload BIRD',
    'birdc configure',
    '',
    'echo "Tunnel $INTERFACE configured successfully"',
  ]

  return lines.join('\n')
}
